"""Write observed values after execution; no marketing effect claims."""
from pathlib import Path

def rows(c,sql):
 cur=c.execute(sql);return [dict(zip([d[0] for d in cur.description],r)) for r in cur.fetchall()]
def pct(v):return '不可计算' if v is None else f'{v:.4%}'
def write_findings(c,out,qa,details,overview,cfg):
 monthly=rows(c,'SELECT * FROM receipt_cohort');equal=rows(c,'SELECT * FROM receipt_cohort_days1_15');types={r['coupon_type']:r for r in rows(c,'SELECT * FROM coupon_type_metrics')};dist={r['distance_group']:r for r in rows(c,'SELECT * FROM distance_metrics')};review={r['comparison_id']:r for r in rows(c,"SELECT * FROM comparison_summary WHERE support_rule='common_min30_each'")};merchant=rows(c,'SELECT * FROM merchant_metrics ORDER BY receipt_records DESC,merchant_id LIMIT 1')[0];md=rows(c,'SELECT * FROM merchant_distribution')[0];lag={r['lag_day']:r for r in rows(c,'SELECT * FROM redemption_lag')};wait=rows(c,'SELECT * FROM redemption_lag_summary')[0]
 lines=['# 阶段2初步发现与可比范围复核','',f'实际执行运行：{details["run_id"]}。来源：阶段1正式库data/o2o.duckdb的线下训练记录。领券窗口2016-01-01至06-15，消费观察至06-30；核销0—15日包含两端，全部领券成熟；保留重复。本文为观察性分析，未执行营销实验，没有ROI或提升测算。','', '## 1. 记录率与用户占比回答不同问题','',f'15日核销记录{overview["redeemed15_records"]:,}/{overview["receipt_records"]:,}，率{pct(overview["redemption_rate15"])}。至少核销一条券的用户{overview["redeemed15_users"]:,}/{overview["receipt_users"]:,}，占比{pct(overview["redemption_user_share15"])}；不能用后者替代记录率，也不能跨组加总独立用户数。普通消费{overview["ordinary_consumption_records"]:,}不进入领券分母。用券消费记录占比{overview["coupon_consumption_records"]:,}/{overview["consumption_records"]:,}={pct(overview["coupon_consumption_record_share"])}，包含超过15日消费，是消费记录结构而非增量。','来源：01_overview.sql → overview.csv。','', '## 2. 月份率与日期构成有关，不解释为季节性','', '|领券月份|领券记录|15日核销|完整窗口率|同月1—15日领券|同月1—15日核销|同日范围率|','|---|---:|---:|---:|---:|---:|---:|']
 for r,e in zip(monthly,equal):lines.append(f'|{r["receipt_month"]}{"（仅1—15日）" if r["receipt_month"]=="2016-06" else ""}|{r["receipt_records"]:,}|{r["redeemed15_records"]:,}|{pct(r["redemption_rate15"])}|{e["receipt_records"]:,}|{e["redeemed15_records"]:,}|{pct(e["redemption_rate15"])}|')
 r=review['march_vs_january'];lines+=['',f'3月完整月份率高于1月，但相同1—15日范围下，3月{pct(equal[2]["redemption_rate15"])}低于1月{pct(equal[0]["redemption_rate15"])}。这说明整体月份排序不能直接归因于月份本身。按相同商家、券方案和距离比较，且每层两月各至少30条时，保留{r["included_strata"]}层：3月覆盖{r["a_common_receipts"]:,}/{r["a_all_receipts"]:,}={pct(r["a_coverage"])}，1月覆盖{r["b_common_receipts"]:,}/{r["b_all_receipts"]:,}={pct(r["b_coverage"])}；同一混合权重标准化率为{pct(r["a_standardized_rate15"])}与{pct(r["b_standardized_rate15"])}。整体差距明显缩小，但覆盖有限，且没有控制用户历史或具体活动日。','可做的后续检查：调查领券日期和活动构成，不能据此写成全年季节性或营销成效。来源：02_receipt_cohort.sql → receipt_cohort.csv / receipt_cohort_days1_15.csv；07_comparable_review.sql → comparison_summary.csv（march_vs_january）。','', '## 3. 券类型总体差异不保证每个月或每个商家都成立','']
 a=types['direct_discount'];b=types['threshold_reduction'];r=review['direct_vs_threshold'];march={x['coupon_type']:x for x in rows(c,"SELECT * FROM coupon_type_month_metrics WHERE receipt_month='2016-03'")}
 lines += [f'直接折扣{a["redeemed15_records"]:,}/{a["receipt_records"]:,}={pct(a["redemption_rate15"])}，满减{b["redeemed15_records"]:,}/{b["receipt_records"]:,}={pct(b["redemption_rate15"])}。但3月直接折扣{march["direct_discount"]["redeemed15_records"]:,}/{march["direct_discount"]["receipt_records"]:,}={pct(march["direct_discount"]["redemption_rate15"])}，低于满减{march["threshold_reduction"]["redeemed15_records"]:,}/{march["threshold_reduction"]["receipt_records"]:,}={pct(march["threshold_reduction"]["redemption_rate15"])}。',f'在相同月份、商家、距离及名义优惠比例档下，每组各至少30条的共同范围仅{r["included_strata"]}层，覆盖直接折扣{pct(r["a_coverage"])}和满减{pct(r["b_coverage"])}。标准化率{pct(r["a_standardized_rate15"])}与{pct(r["b_standardized_rate15"])}，但名义比例分档不能控制满减门槛，也没有控制用户选择；不代表券类型的普遍优劣。','', '|同门槛券方案A/B|总体A率|总体B率|严格共同范围层数|A覆盖|B覆盖|标准化A率|标准化B率|','|---|---:|---:|---:|---:|---:|---:|---:|']
 for cid in ['20_5_vs_20_1','100_30_vs_100_10']:
  r=review[cid];lines.append(f'|{r["group_a"]} / {r["group_b"]}|{pct(r["a_all_rate15"])}|{pct(r["b_all_rate15"])}|{r["included_strata"]}|{pct(r["a_coverage"])}|{pct(r["b_coverage"])}|{pct(r["a_standardized_rate15"])}|{pct(r["b_standardized_rate15"])}|')
 lines+=['','两组同门槛比较在严格共同子样本中方向反转，但覆盖率极低，因此既不能把总体排名当券力度效果，也不能把反转推广到全部商家。common_min1和common_min30_each两种门槛均已输出，结果对共同支持要求敏感；这些数字适合提出后续验证问题，不支持优惠力度与增量核销的结论。','来源：03_coupon.sql → coupon_type_metrics.csv / coupon_type_month_metrics.csv / coupon_scheme_metrics.csv；07_comparable_review.sql → comparison_cells.csv / comparison_strata.csv / comparison_summary.csv。','', '## 4. 距离编码差异在可比范围中仍存在','']
 a=dist['0'];b=dist['10'];u=dist['unknown'];r=review['distance0_vs10']
 lines += [f'编码0：{a["redeemed15_records"]:,}/{a["receipt_records"]:,}={pct(a["redemption_rate15"])}；编码10：{b["redeemed15_records"]:,}/{b["receipt_records"]:,}={pct(b["redemption_rate15"])}。未知距离{u["redeemed15_records"]:,}/{u["receipt_records"]:,}={pct(u["redemption_rate15"])}，已单独保留。',f'同月份、同商家、同券方案且两侧各至少30条时，共{r["included_strata"]}层，编码0覆盖{pct(r["a_coverage"])}，编码10覆盖{pct(r["b_coverage"])}；标准化率{pct(r["a_standardized_rate15"])}与{pct(r["b_standardized_rate15"])}，方向保留而差距缩小。可把距离构成纳入活动诊断，但不能推断精确公里数、距离导致核销下降或缩短距离会产生多少提升。','来源：04_distance.sql → distance_metrics.csv / distance_month_metrics.csv；07_comparable_review.sql → comparison_summary.csv（distance0_vs10）。','', '## 5. 大规模低率商家需要结构诊断，小样本不强排','']
 r=review['largest_merchant_vs_peers'];lines += [f'有效领券涉及{md["merchant_count"]:,}个商家，中位数{md["median_receipts"]:g}条领券；{md["small_sample_merchants"]:,}个商家不足{cfg["small_sample_receipts"]}条。此阈值只作提示，达到100条也不代表稳定或显著。',f'按领券量选出的最大商家{merchant["merchant_id"]}：{merchant["redeemed15_records"]:,}/{merchant["receipt_records"]:,}={pct(merchant["redemption_rate15"])}。在同月份、同券方案、同距离的共同范围下，其保留{r["a_common_receipts"]:,}条、覆盖{pct(r["a_coverage"])}；其他商家保留{r["b_common_receipts"]:,}条、覆盖{pct(r["b_coverage"])}。标准化率为{pct(r["a_standardized_rate15"])}与{pct(r["b_standardized_rate15"])}，差异小于其与全部其他商家的总体差异。参照覆盖很窄；剩余差异还可能涉及用户、商品或活动安排，不能直接判定运营能力或利润。','来源：05_merchant.sql → merchant_metrics.csv / merchant_structure.csv / merchant_distribution.csv；07_comparable_review.sql → comparison_summary.csv（largest_merchant_vs_peers）。','', '## 6. 核销时间要区分成功者分布与全体领券累计率','',f'成功15日核销记录的等待中位数为{wait["median_wait_days"]:g}天，均值{wait["mean_wait_days"]:.2f}天。第7日累计核销{lag[7]["cumulative_redeemed15_records"]:,}条：占全部15日成功核销{pct(lag[7]["cumulative_share_of_successes"])}，但占全部领券仅{pct(lag[7]["cumulative_redemption_rate15"])}。第15日累计{lag[15]["cumulative_redeemed15_records"]:,}与总体完全一致。','观察分布可为提醒时间的后续实验提供参考，但本数据没有提醒记录或随机对照，当前不选择“已验证最优提醒日”，不测算提醒提升。来源：06_redemption_lag.sql → redemption_lag.csv / redemption_lag_summary.csv / redemption_lag_by_coupon_type.csv。','', '## 复核方法与边界','', '对比均使用同一成熟领券群体与记录级分子分母。共同层按已观察维度精确匹配；两侧均出现为common_min1，两侧每层至少30条为common_min30_each。标准权重为共同层两侧领券数之和w，标准化率=SUM(w×层内核销率)/SUM(w)。标准化分子是带权的等效核销量，不是实际观测核销条数，已明确命名standardized_numerator_receipt_equivalents。原始全体/共同范围的真实条数均单独保留。','', '标准化不是随机化、不是完整去混杂、不是显著性检验；用户可以多次领券，当前不以记录独立假设生成置信区间。名义比例档仅为描述，边界先舍入10位以避免0.95的二进制浮点误入下一档。小样本阈值与比较选择理由写入config/stage2.json及review_selection.json。未知类别保留，无共同覆盖或零分母显示不可计算，不填0%。','', '各CSV的粒度、SQL、日期、过滤和输入版本见manifest.json；独立复算、分组对账和第15日检查见对应qa运行目录。结果来自2016年公开竞赛格式数据，不能当作当前市场或行业基准。没有成本/收入，不计算ROI；用户级历史分层见阶段3，未实施线上关联或Tableau看板。']
 (out/'初步发现.md').write_text('\n'.join(lines)+'\n',encoding='utf-8')
